// Spec: 0053-sql-typed FR-008
/**
 * The typed tables of the proof model, generated by IFC Data from the model. Do not edit: change the model and run `bun tools/typed.ts --write`.
 *
 * The proof that a platform can be put right and that its figures are right
 *
 * @module
 */
import { defineTable, type Timestamp } from "@intellectual-frontiers/data/sql/typed";

/** One drill of a recovery: what was tested (a replay, a rollback or a restore), against which load or scope, how long it took, what it found and the evidence, so that a recovery is shown and not assumed */
export interface DrillRow {
  /** What identifies the drill */
  readonly drillId: string;
  /** What it tested */
  readonly kind: "replay" | "rollback" | "restore";
  /** What it was done to: a load id, a table or a store */
  readonly scope: string;
  /** When it began */
  readonly startedAt: Timestamp;
  /** How long it took, in whole seconds */
  readonly seconds: number;
  /** What it found */
  readonly outcome: "passed" | "failed" | "abandoned";
  /** The hash of what was there before */
  readonly beforeHash: string | null;
  /** The hash of what was there after */
  readonly afterHash: string | null;
  /** Where the evidence is kept */
  readonly evidence: string | null;
}

/** What an insert into drill takes: what the database fills may be left out. */
export interface DrillInsert {
  readonly drillId: string;
  readonly kind: "replay" | "rollback" | "restore";
  readonly scope: string;
  readonly startedAt: Timestamp;
  readonly seconds: number;
  readonly outcome: "passed" | "failed" | "abandoned";
  readonly beforeHash?: string | null;
  readonly afterHash?: string | null;
  readonly evidence?: string | null;
}

/** The key of a row of drill. */
export type DrillKey = { readonly drillId: string };

/** One drill of a recovery: what was tested (a replay, a rollback or a restore), against which load or scope, how long it took, what it found and the evidence, so that a recovery is shown and not assumed */
export const drill = defineTable<DrillRow, DrillInsert, "drill">({
  alias: "drill",
  name: "drill",
  columns: {
    drillId: "drill_id",
    kind: "kind",
    scope: "scope",
    startedAt: "started_at",
    seconds: "seconds",
    outcome: "outcome",
    beforeHash: "before_hash",
    afterHash: "after_hash",
    evidence: "evidence",
  },
  primaryKey: ["drillId"],
});

/** One run of a calculation: its name and version, the parameters it ran with, the hash of its inputs and of its outputs and how many rows it gave, so that a figure can be reproduced and a change of one shown */
export interface CalculationRunRow {
  /** What identifies the run */
  readonly calculationRunId: string;
  /** The calculation */
  readonly calculation: string;
  /** Its version */
  readonly version: string;
  /** The parameters it ran with, as JSON */
  readonly parameters: string | null;
  /** The SHA-256 of its inputs */
  readonly inputHash: string;
  /** The SHA-256 of its outputs */
  readonly outputHash: string;
  /** How many rows it gave */
  readonly rows: number;
  /** When */
  readonly ranAt: Timestamp;
  /** The load it was run for, where it was */
  readonly loadId: string | null;
}

/** What an insert into calculation_run takes: what the database fills may be left out. */
export interface CalculationRunInsert {
  readonly calculationRunId: string;
  readonly calculation: string;
  readonly version: string;
  readonly parameters?: string | null;
  readonly inputHash: string;
  readonly outputHash: string;
  readonly rows: number;
  readonly ranAt: Timestamp;
  readonly loadId?: string | null;
}

/** The key of a row of calculation_run. */
export type CalculationRunKey = { readonly calculationRunId: string };

/** One run of a calculation: its name and version, the parameters it ran with, the hash of its inputs and of its outputs and how many rows it gave, so that a figure can be reproduced and a change of one shown */
export const calculationRun = defineTable<CalculationRunRow, CalculationRunInsert, "calculationRun">({
  alias: "calculationRun",
  name: "calculation_run",
  columns: {
    calculationRunId: "calculation_run_id",
    calculation: "calculation",
    version: "version",
    parameters: "parameters",
    inputHash: "input_hash",
    outputHash: "output_hash",
    rows: "rows",
    ranAt: "ran_at",
    loadId: "load_id",
  },
  primaryKey: ["calculationRunId"],
});

/** A case with inputs and the value a calculation must give for them, found by hand or from a source that is trusted, with how close it must be: what a calculation is held to */
export interface ReferenceCaseRow {
  /** What identifies the case */
  readonly referenceCaseId: string;
  /** The calculation it is for */
  readonly calculation: string;
  /** What the case shows */
  readonly description: string;
  /** The inputs, as JSON */
  readonly inputs: string;
  /** The value it must give, as a number */
  readonly expected: string;
  /** How far it may be from the value, as a number: 0 for exact */
  readonly tolerance: string;
  /** Where the value comes from */
  readonly source: string;
}

/** What an insert into reference_case takes: what the database fills may be left out. */
export interface ReferenceCaseInsert {
  readonly referenceCaseId: string;
  readonly calculation: string;
  readonly description: string;
  readonly inputs: string;
  readonly expected: string;
  readonly tolerance: string;
  readonly source: string;
}

/** The key of a row of reference_case. */
export type ReferenceCaseKey = { readonly referenceCaseId: string };

/** A case with inputs and the value a calculation must give for them, found by hand or from a source that is trusted, with how close it must be: what a calculation is held to */
export const referenceCase = defineTable<ReferenceCaseRow, ReferenceCaseInsert, "referenceCase">({
  alias: "referenceCase",
  name: "reference_case",
  columns: {
    referenceCaseId: "reference_case_id",
    calculation: "calculation",
    description: "description",
    inputs: "inputs",
    expected: "expected",
    tolerance: "tolerance",
    source: "source",
  },
  primaryKey: ["referenceCaseId"],
});

