/** A record of one source linked to an entity that other sources also hold, with the rule that found it and the score, so that who is the same person or thing is a fact with a reason and not a guess */
export interface EntityLinkRow {
  /** What identifies the link: the source and the key of its record */
  readonly entityLinkId: string;
  /** The entity it is linked to */
  readonly entityId: string;
  /** The source */
  readonly source: string;
  /** The key of the record in the source */
  readonly sourceKey: string;
  /** How it was found */
  readonly rule: "exact" | "normalized" | "similar" | "confirmed";
  /** How sure, as a number from 0 to 1 */
  readonly score: string;
}

/** What an insert into entity_link takes: what the database fills may be left out. */
export interface EntityLinkInsert {
  readonly entityLinkId: string;
  readonly entityId: string;
  readonly source: string;
  readonly sourceKey: string;
  readonly rule: "exact" | "normalized" | "similar" | "confirmed";
  readonly score: string;
}

/** The key of a row of entity_link. */
export type EntityLinkKey = { readonly entityLinkId: string };

/** A record of one source linked to an entity that other sources also hold, with the rule that found it and the score, so that who is the same person or thing is a fact with a reason and not a guess */
export const entityLink = defineTable<EntityLinkRow, EntityLinkInsert, "entityLink">({
  alias: "entityLink",
  name: "entity_link",
  columns: {
    entityLinkId: "entity_link_id",
    entityId: "entity_id",
    source: "source",
    sourceKey: "source_key",
    rule: "rule",
    score: "score",
  },
  primaryKey: ["entityLinkId"],
});
